function drawShip() {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    // ship body with subtle gradient
    const grad = ctx.createLinearGradient(0, -12, 0, 12);
    grad.addColorStop(0, ship.shield ? 'cyan' : '#99d');
    grad.addColorStop(1, ship.shield ? '#33f' : '#fff');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(12, 0);
    ctx.lineTo(-8, -6);
    ctx.lineTo(-8, 6);
    ctx.closePath();
    ctx.fill();
    // thrust flame
    if (ship.thrusting) {
      ctx.fillStyle = 'orange';
      ctx.beginPath();
      ctx.moveTo(-8, -4);
      ctx.lineTo(-14, 0);
      ctx.lineTo(-8, 4);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

